// intro(2) describes entry points into the Kernel

// 1. Standard C library wrapper (Preferred)
pid_t child_pid = fork();

// 2. Direct kernel entry via syscall(2)
// (Requires defined syscall number, e.g., SYS_read)
long result = syscall(SYS_read, fd, buf, count);

// 3. Error indication (described in intro(2))
// Wrappers return -1 and set global errno
if (result == -1) {
    int error_val = errno;
}

